import pandas as pd
import numpy as np

class DecisionTree:
    def __init__(self, max_depth=3):
        self.max_depth = max_depth
        self.tree = {}

    def fit(self, X, y):
        self.tree = self._grow(X, y, 0)

    def _grow(self, X, y, depth):
        if depth >= self.max_depth or len(np.unique(y)) == 1 or len(y) < 2:
            return np.mean(y)

        n_features = X.shape[1]
        best_gain = -1
        best_split = None

        # subset of features
        features = np.random.choice(n_features, max(1, int(np.sqrt(n_features))), replace=False)
        for feat in features:
            vals = X[:, feat]
            thresholds = np.random.choice(vals, min(10, len(vals)), replace=False)
            for t in thresholds:
                left_mask = vals < t
                right_mask = ~left_mask
                if np.sum(left_mask) == 0 or np.sum(right_mask) == 0: continue

                p_left = np.sum(left_mask) / len(y)
                p_right = 1 - p_left
                var_y = np.var(y)
                var_left = np.var(y[left_mask])
                var_right = np.var(y[right_mask])

                gain = var_y - (p_left * var_left + p_right * var_right)
                if gain > best_gain:
                    best_gain = gain
                    best_split = (feat, t, left_mask, right_mask)

        if best_split is None or best_gain < 1e-6:
            return np.mean(y)

        feat, t, left_mask, right_mask = best_split
        left_child = self._grow(X[left_mask], y[left_mask], depth + 1)
        right_child = self._grow(X[right_mask], y[right_mask], depth + 1)
        return (feat, t, left_child, right_child)

    def _predict_one(self, x, node):
        if not isinstance(node, tuple): return node
        feat, t, left, right = node
        if x[feat] < t: return self._predict_one(x, left)
        else: return self._predict_one(x, right)

    def predict(self, X):
        return np.array([self._predict_one(x, self.tree) for x in X])

train = pd.read_csv('train.csv').sample(10000)
X = train.drop('target', axis=1).values
y = train['target'].values

preds = np.zeros(len(y))
for i in range(10):
    idx = np.random.choice(len(X), len(X), replace=True)
    tree = DecisionTree(max_depth=5)
    tree.fit(X[idx], y[idx])
    preds += tree.predict(X)
    print('Tree', i, 'done')

acc = np.mean((preds / 10 > 0.5) == y)
print('RF train accuracy:', acc)
