import pandas as pd
import numpy as np
import math

def normalize_label(value: object) -> str:
    if pd.isna(value): return '<NA>'
    if isinstance(value, str): return value.strip().removesuffix('.')
    if isinstance(value, (int, np.integer)): return str(int(value))
    if isinstance(value, (float, np.floating)):
        number = float(value)
        if math.isfinite(number) and number.is_integer(): return str(int(number))
        return f'{number:.12g}'
    return str(value).strip().removesuffix('.')

y_true = pd.read_csv('test.csv')['target']
y_pred = pd.read_csv('predictions.csv')['prediction']

truth = y_true.map(normalize_label)
pred = y_pred.map(normalize_label)
print('Accuracy:', float((truth == pred).mean()))
"

